// Checks the port against what the repository holds: the known values, the
// vectors of the checked-in Foundry tests (generated by the TS reference
// permutation) and the checked-in Huff output, which is the raw output of
// the TS generator (forge fmt leaves .huff files and these tests as they
// are). generator-rs/parity.sh compares every target against the TS itself.

use std::fs;
use std::path::{Path, PathBuf};

use poseidon2_gen::assert_known::assert_known;
use poseidon2_gen::field::U256;
use poseidon2_gen::huff::fork::fork;
use poseidon2_gen::reference::permutation;
use poseidon2_gen::round_constants::generate_params;
use poseidon2_gen::vectors::test_inputs;
use poseidon2_gen::{huff, yul};

fn repo() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("..")
}

/// A fresh directory for one test's output.
fn scratch(name: &str) -> PathBuf {
    let dir = std::env::temp_dir().join(format!("poseidon2-gen-{}-{name}", std::process::id()));
    let _ = fs::remove_dir_all(&dir);
    fs::create_dir_all(&dir).expect("scratch directory");
    dir
}

/// The uint256(0x...) words of a test file in order: per vector its t
/// inputs, then its t outputs.
fn words(path: &Path) -> Vec<U256> {
    let text = fs::read_to_string(path).expect("test file");
    text.split("uint256(0x")
        .skip(1)
        .map(|w| U256::from_str_radix(&w[..64], 16).expect("hex word"))
        .collect()
}

fn same_file(generated: &Path, checked_in: &Path) {
    let a = fs::read(generated).unwrap_or_else(|_| panic!("{} not generated", generated.display()));
    let b = fs::read(checked_in).expect("checked-in file");
    assert!(
        a == b,
        "{} differs from {}",
        generated.display(),
        checked_in.display()
    );
}

#[test]
fn known_values() {
    assert_known().expect("known values");
}

#[test]
fn reference_reproduces_checked_in_vectors() {
    let tests = repo().join("test");
    let files = [2, 3, 8, 12, 16, 20, 24, 28]
        .map(|t| (t, tests.join(format!("Poseidon2T{t}.t.sol"))))
        .into_iter()
        .chain([2, 3, 8, 12].map(|t| (t, tests.join(format!("Poseidon2YulT{t}.t.sol")))));
    for (t, path) in files {
        let params = generate_params(t);
        let inputs = test_inputs(t);
        let mut expected = Vec::new();
        for input in &inputs {
            expected.extend_from_slice(input);
            expected.extend(permutation(&params, input));
        }
        assert_eq!(words(&path), expected, "{}", path.display());
    }
}

#[test]
fn huff_matches_checked_in() {
    let out = scratch("huff");
    fs::create_dir_all(out.join("src/bn254/huff/t4")).unwrap();
    fs::create_dir_all(out.join("test")).unwrap();
    huff::run(&out, &fork("amsterdam").unwrap(), &[2, 3, 4], || Ok(())).expect("huff 2 3 4");
    let mut files = vec![
        "src/bn254/huff/Eip8024.huff".to_string(),
        "src/bn254/huff/t4/Permutation.huff".to_string(),
    ];
    for t in [2, 3] {
        files.push(format!("src/bn254/huff/t{t}/Permutation.huff"));
        files.push(format!("src/bn254/huff/t{t}/Poseidon2.huff"));
        files.push(format!("test/Poseidon2T{t}.t.sol"));
    }
    for file in &files {
        same_file(&out.join(file), &repo().join(file));
    }
    fs::remove_dir_all(out).unwrap();
}

#[test]
fn yul_tests_match_checked_in() {
    let out = scratch("yul");
    fs::create_dir_all(out.join("test")).unwrap();
    yul::run(&out, &[2, 3], || Ok(())).expect("yul 2 3");
    // the libraries in the repository went through forge fmt, the tests are
    // as generated
    for t in [2, 3] {
        let file = format!("test/Poseidon2YulT{t}.t.sol");
        same_file(&out.join(&file), &repo().join(&file));
    }
    fs::remove_dir_all(out).unwrap();
}
